def candidate_loose_files(vault: Path, names: set[str]):
    for p in vault.rglob('*'):
        if p.is_file() and p.name in names and p.suffix.lower() != '.zip':
            yield p


def zip_files(vault: Path):
    return sorted((p for p in vault.rglob('*.zip') if p.is_file()), key=lambda p: str(p).lower())


def find_exact_sources(vault: Path, basenames: list[str], expected_sha: str, zip_cache):
    names = set(basenames)
    hits = []

    # Loose/extracted copies.
    for p in candidate_loose_files(vault, names):
        try:
            if sha256_file(p) == expected_sha:
                hits.append({'kind':'file','source':str(p),'path':p})
        except OSError:
            pass

    # Members inside original ZIP evidence packages.
    for zp, members in zip_cache.items():
        matching = [m for m in members if Path(m).name in names and not m.endswith('/')]
        if not matching:
            continue
        with zipfile.ZipFile(zp) as z:
            for member in matching:
                data = z.read(member)
                if sha256_bytes(data) == expected_sha:
                    hits.append({'kind':'zip','source':f'{zp}::{member}','zip':zp,'member':member})
    return hits


def restore_one(hit, dest: Path):
    dest.parent.mkdir(parents=True, exist_ok=True)
    if hit['kind'] == 'file':
        shutil.copy2(hit['path'], dest)
    else:
        with zipfile.ZipFile(hit['zip']) as z:
            data = z.read(hit['member'])
        dest.write_bytes(data)


def main():
    ap = argparse.ArgumentParser(description='Restore exact DamageACT-U canonical artifacts from loose files or original ZIP packages.')
    ap.add_argument('--evidence-vault', required=True)
    ap.add_argument('--repo-root', default='.', help='DamageACT-U repository root (default: current directory).')
    ap.add_argument('--report', default='audit/restoration_report_v2.json')
    args = ap.parse_args()

    vault = Path(args.evidence_vault).resolve()
    repo = Path(args.repo_root).resolve()
    if not vault.is_dir():
        raise FileNotFoundError(vault)
    if not (repo / 'pyproject.toml').is_file():
        raise RuntimeError(f'--repo-root does not look like the DamageACT-U repository: {repo}')

    # Read only ZIP central directories first. Large segment-state ZIPs are not decompressed unless a basename matches.
    zip_cache = {}
    for zp in zip_files(vault):
        try:
            with zipfile.ZipFile(zp) as z:
                zip_cache[zp] = z.namelist()
        except zipfile.BadZipFile:
            print('WARNING: bad ZIP skipped:', zp)

    report = {
        'vault': str(vault),
        'repo_root': str(repo),
        'artifacts': [],
        'summary': {},
    }
    failures = 0

    for label, basenames, expected, rel_dest in ARTIFACTS:
        dest = repo / rel_dest

        # Never silently overwrite a non-canonical destination.
        if dest.is_file():
            got = sha256_file(dest)
            if got == expected:
                print(f'ALREADY VERIFIED: {label} -> {rel_dest}')
                report['artifacts'].append({
                    'label':label,'status':'already_verified','destination':rel_dest,
                    'expected_sha256':expected,'actual_sha256':got,'sources':[]
                })
                continue
            print(f'ERROR DESTINATION HASH MISMATCH: {label}\n  {dest}\n  expected={expected}\n  actual  ={got}')
            report['artifacts'].append({
                'label':label,'status':'destination_hash_mismatch','destination':rel_dest,
                'expected_sha256':expected,'actual_sha256':got,'sources':[]
            })
            failures += 1
            continue

        hits = find_exact_sources(vault, basenames, expected, zip_cache)
        if not hits:
            print(f'MISSING EXACT ARTIFACT: {label} | basenames={basenames} | sha256={expected}')
            report['artifacts'].append({
                'label':label,'status':'missing','destination':rel_dest,
                'expected_sha256':expected,'sources':[]
            })
            failures += 1
            continue

        # Multiple valid hits are byte-identical by construction; preserve provenance and choose deterministically.
        hits = sorted(hits, key=lambda h: h['source'].lower())
        chosen = hits[0]
        restore_one(chosen, dest)
        got = sha256_file(dest)
        if got != expected:
            raise RuntimeError(f'Post-copy hash mismatch for {label}: {got} != {expected}')
        print(f'RESTORED: {label} -> {rel_dest} | exact_copies_found={len(hits)}')
        report['artifacts'].append({
            'label':label,'status':'restored','destination':rel_dest,
            'expected_sha256':expected,'actual_sha256':got,
            'chosen_source':chosen['source'],'sources':[h['source'] for h in hits]
        })

    counts = {}
    for row in report['artifacts']:
        counts[row['status']] = counts.get(row['status'], 0) + 1
    report['summary'] = counts
    report_path = repo / args.report
    report_path.parent.mkdir(parents=True, exist_ok=True)
    report_path.write_text(json.dumps(report, indent=2), encoding='utf-8')

    print('\nRESTORATION SUMMARY:', json.dumps(counts, sort_keys=True))
    print('REPORT:', report_path)
    if failures:
        raise SystemExit(f'RESTORATION INCOMPLETE: {failures} required canonical artifacts were not restored/verified.')
    print('RESTORATION COMPLETE: every listed canonical artifact is hash-verified.')


if __name__ == '__main__':
    main()
